      egg: ['Egg-free', 'अंडा-मुक्त', 'अंडे-मुक्त', 'ઈંડા-મુક્ત', 'ডিম-মুক্ত', 'ਅੰਡਾ-ਰਹਿਤ', 'முட்டை இல்லாத', 'గుడ్డు లేని', 'ಮೊಟ್ಟೆ ರಹಿತ', 'മുട്ട രഹിതം'],
      fish: ['Fish-free', 'मछली-मुक्त', 'मासे-मुक्त', 'માછલી-મુક્ત', 'মাছ-মুক্ত', 'ਮੱਛੀ-ਰਹਿਤ', 'மீன் இல்லாத', 'చేపలు లేని', 'ಮೀನು ರಹಿತ', 'മീൻ രഹിതം'],
