  // ── Guidelines ({water}, {avg}, {target} are filled in) ─────────
  const TIPS = table({
    water: ['Drink about {water} L of water through the day.', 'दिन भर में लगभग {water} लीटर पानी पिएं।', 'दिवसभरात सुमारे {water} लिटर पाणी प्या.', 'દિવસ દરમિયાન લગભગ {water} લિટર પાણી પીવો.', 'সারাদিনে প্রায় {water} লিটার জল পান করুন।', 'ਦਿਨ ਭਰ ਵਿੱਚ ਲਗਭਗ {water} ਲੀਟਰ ਪਾਣੀ ਪੀਓ।', 'நாள் முழுவதும் சுமார் {water} லிட்டர் தண்ணீர் குடிக்கவும்.', 'రోజంతా సుమారు {water} లీటర్ల నీరు తాగండి.', 'ದಿನವಿಡೀ ಸುಮಾರು {water} ಲೀಟರ್ ನೀರು ಕುಡಿಯಿರಿ.', 'ദിവസം മുഴുവൻ ഏകദേശം {water} ലിറ്റർ വെള്ളം കുടിക്കുക.'],
    plate: ['Fill half your plate with vegetables or salad at lunch and dinner.', 'दोपहर और रात के भोजन में आधी थाली सब्ज़ी या सलाद से भरें।', 'दुपारच्या व रात्रीच्या जेवणात अर्धे ताट भाज्या किंवा कोशिंबिरीने भरा.', 'બપોર અને રાત્રિના ભોજનમાં અડધી થાળી શાકભાજી કે સલાડથી ભરો.', 'দুপুর ও রাতের খাবারে থালার অর্ধেক সবজি বা স্যালাড রাখুন।', 'ਦੁਪਹਿਰ ਅਤੇ ਰਾਤ ਦੇ ਖਾਣੇ ਵਿੱਚ ਅੱਧੀ ਥਾਲੀ ਸਬਜ਼ੀਆਂ ਜਾਂ ਸਲਾਦ ਨਾਲ ਭਰੋ।', 'மதியம் மற்றும் இரவு உணவில் தட்டின் பாதியை காய்கறி அல்லது சாலட்டால் நிரப்பவும்.', 'మధ్యాహ్నం మరియు రాత్రి భోజనంలో సగం ప్లేట్ కూరగాయలు లేదా సలాడ్‌తో నింపండి.', 'ಮಧ್ಯಾಹ್ನ ಮತ್ತು ರಾತ್ರಿ ಊಟದಲ್ಲಿ ಅರ್ಧ ತಟ್ಟೆ ತರಕಾರಿ ಅಥವಾ ಸಲಾಡ್‌ನಿಂದ ತುಂಬಿಸಿ.', 'ഉച്ചയ്ക്കും രാത്രിയും പ്ലേറ്റിന്റെ പകുതി പച്ചക്കറികളോ സാലഡോ കൊണ്ട് നിറയ്ക്കുക.'],
    oil: ['Use 3–4 tsp of oil per person per day (mustard, groundnut or rice-bran oil).', 'प्रति व्यक्ति प्रतिदिन 3–4 छोटे चम्मच तेल ही लें (सरसों, मूंगफली या राइस ब्रान तेल)।', 'प्रति व्यक्ती दररोज 3–4 छोटे चमचे तेल वापरा (मोहरी, शेंगदाणा किंवा राइस ब्रान तेल).', 'વ્યક્તિ દીઠ દરરોજ 3–4 ચમચી તેલ વાપરો (રાઈ, સીંગતેલ અથવા રાઇસ બ્રાન તેલ).', 'মাথাপিছু দিনে 3–4 চা চামচ তেল ব্যবহার করুন (সরষে, চিনাবাদাম বা রাইস ব্র্যান তেল)।', 'ਪ੍ਰਤੀ ਵਿਅਕਤੀ ਰੋਜ਼ਾਨਾ 3–4 ਛੋਟੇ ਚਮਚ ਤੇਲ ਵਰਤੋ (ਸਰ੍ਹੋਂ, ਮੂੰਗਫਲੀ ਜਾਂ ਰਾਈਸ ਬ੍ਰੈਨ ਤੇਲ)।', 'ஒருவருக்கு நாளொன்றுக்கு 3–4 தேக்கரண்டி எண்ணெய் மட்டும் பயன்படுத்தவும் (கடுகு, கடலை அல்லது அரிசி தவிடு எண்ணெய்).', 'ఒక్కొక్కరికి రోజుకు 3–4 టీ స్పూన్ల నూనె మాత్రమే వాడండి (ఆవ, వేరుశెనగ లేదా రైస్ బ్రాన్ నూనె).', 'ಒಬ್ಬರಿಗೆ ದಿನಕ್ಕೆ 3–4 ಟೀ ಚಮಚ ಎಣ್ಣೆ ಮಾತ್ರ ಬಳಸಿ (ಸಾಸಿವೆ, ಕಡಲೆಕಾಯಿ ಅಥವಾ ರೈಸ್ ಬ್ರಾನ್ ಎಣ್ಣೆ).', 'ഒരാൾക്ക് ദിവസം 3–4 ടീസ്പൂൺ എണ്ണ മാത്രം ഉപയോഗിക്കുക (കടുക്, നിലക്കടല അല്ലെങ്കിൽ റൈസ് ബ്രാൻ എണ്ണ).'],
    travel: ['Travel: carry fruit, roasted chana, makhana and nuts; choose dal–roti–sabzi or grilled food over fried food.', 'यात्रा: फल, भुने चने, मखाने और मेवे साथ रखें; तले भोजन की जगह दाल–रोटी–सब्ज़ी या ग्रिल्ड भोजन चुनें।', 'प्रवास: फळे, भाजलेले चणे, मखाणे व सुकामेवा सोबत ठेवा; तळलेल्या पदार्थांऐवजी वरण–पोळी–भाजी किंवा ग्रिल्ड पदार्थ निवडा.', 'મુસાફરી: ફળ, શેકેલા ચણા, મખાના અને સૂકો મેવો સાથે રાખો; તળેલાને બદલે દાળ–રોટલી–શાક કે ગ્રિલ્ડ ખોરાક પસંદ કરો.', 'ভ্রমণ: ফল, ভাজা ছোলা, মাখানা ও বাদাম সঙ্গে রাখুন; ভাজা খাবারের বদলে ডাল–রুটি–সবজি বা গ্রিলড খাবার বেছে নিন।', 'ਯਾਤਰਾ: ਫਲ, ਭੁੰਨੇ ਛੋਲੇ, ਮਖਾਣੇ ਅਤੇ ਮੇਵੇ ਨਾਲ ਰੱਖੋ; ਤਲੇ ਭੋਜਨ ਦੀ ਬਜਾਏ ਦਾਲ–ਰੋਟੀ–ਸਬਜ਼ੀ ਜਾਂ ਗ੍ਰਿਲਡ ਭੋਜਨ ਚੁਣੋ।', 'பயணம்: பழங்கள், வறுத்த கடலை, மக்கானா மற்றும் பருப்புகளை எடுத்துச் செல்லவும்; பொரித்த உணவுக்குப் பதிலாக பருப்பு–சப்பாத்தி–காய்கறி அல்லது கிரில் உணவைத் தேர்ந்தெடுக்கவும்.', 'ప్రయాణం: పండ్లు, వేయించిన శనగలు, మఖానా మరియు గింజలు వెంట తీసుకెళ్లండి; వేపుళ్లకు బదులు పప్పు–రొట్టె–కూర లేదా గ్రిల్ ఆహారం ఎంచుకోండి.', 'ಪ್ರಯಾಣ: ಹಣ್ಣು, ಹುರಿದ ಕಡಲೆ, ಮಖಾನಾ ಮತ್ತು ಬೀಜಗಳನ್ನು ಜೊತೆಗಿಡಿ; ಕರಿದ ಆಹಾರದ ಬದಲು ಬೇಳೆ–ರೊಟ್ಟಿ–ಪಲ್ಯ ಅಥವಾ ಗ್ರಿಲ್ ಆಹಾರ ಆರಿಸಿ.', 'യാത്ര: പഴങ്ങൾ, വറുത്ത കടല, മഖാന, നട്സ് എന്നിവ കരുതുക; വറുത്തതിന് പകരം പരിപ്പ്–ചപ്പാത്തി–കറി അല്ലെങ്കിൽ ഗ്രിൽ ചെയ്ത ഭക്ഷണം തിരഞ്ഞെടുക്കുക.'],
    flight: ['Flight: drink water every hour; avoid sugary drinks and alcohol.', 'हवाई यात्रा: हर घंटे पानी पिएं; मीठे पेय और शराब से बचें।', 'विमान प्रवास: दर तासाला पाणी प्या; गोड पेये व मद्य टाळा.', 'હવાઈ મુસાફરી: દર કલાકે પાણી પીવો; ખાંડવાળાં પીણાં અને દારૂ ટાળો.', 'বিমান যাত্রা: প্রতি ঘণ্টায় জল পান করুন; মিষ্টি পানীয় ও মদ এড়িয়ে চলুন।', 'ਹਵਾਈ ਯਾਤਰਾ: ਹਰ ਘੰਟੇ ਪਾਣੀ ਪੀਓ; ਮਿੱਠੇ ਪੀਣ ਵਾਲੇ ਪਦਾਰਥ ਅਤੇ ਸ਼ਰਾਬ ਤੋਂ ਬਚੋ।', 'விமானப் பயணம்: ஒவ்வொரு மணி நேரமும் தண்ணீர் குடிக்கவும்; இனிப்பு பானங்கள் மற்றும் மதுவைத் தவிர்க்கவும்.', 'విమాన ప్రయాణం: ప్రతి గంటకు నీరు తాగండి; తీపి పానీయాలు మరియు మద్యం మానండి.', 'ವಿಮಾನ ಪ್ರಯಾಣ: ಪ್ರತಿ ಗಂಟೆಗೆ ನೀರು ಕುಡಿಯಿರಿ; ಸಿಹಿ ಪಾನೀಯ ಮತ್ತು ಮದ್ಯ ತಪ್ಪಿಸಿ.', 'വിമാനയാത്ര: ഓരോ മണിക്കൂറിലും വെള്ളം കുടിക്കുക; മധുരപാനീയങ്ങളും മദ്യവും ഒഴിവാക്കുക.'],
    train: ['Train: carry thepla, idli, khakhra or curd rice from home; drink only sealed water.', 'ट्रेन: घर से थेपला, इडली, खाखरा या दही-चावल ले जाएं; केवल सील बंद पानी पिएं।', 'रेल्वे: घरून थेपला, इडली, खाखरा किंवा दही-भात न्या; फक्त सीलबंद पाणी प्या.', 'ટ્રેન: ઘરેથી થેપલા, ઈડલી, ખાખરા કે દહીં-ભાત લઈ જાઓ; માત્ર સીલબંધ પાણી પીવો.', 'ট্রেন: বাড়ি থেকে থেপলা, ইডলি, খাখরা বা দই-ভাত নিয়ে যান; শুধু সিল করা জল পান করুন।', 'ਰੇਲ: ਘਰੋਂ ਥੇਪਲਾ, ਇਡਲੀ, ਖਾਖਰਾ ਜਾਂ ਦਹੀਂ-ਚੌਲ ਲੈ ਕੇ ਜਾਓ; ਸਿਰਫ਼ ਸੀਲਬੰਦ ਪਾਣੀ ਪੀਓ।', 'ரயில்: வீட்டிலிருந்து தேப்லா, இட்லி, காக்ரா அல்லது தயிர் சாதம் எடுத்துச் செல்லவும்; சீல் செய்யப்பட்ட தண்ணீர் மட்டும் குடிக்கவும்.', 'రైలు: ఇంటి నుంచి తేప్లా, ఇడ్లీ, ఖాఖ్రా లేదా పెరుగన్నం తీసుకెళ్లండి; సీల్ చేసిన నీరు మాత్రమే తాగండి.', 'ರೈಲು: ಮನೆಯಿಂದ ಥೇಪ್ಲಾ, ಇಡ್ಲಿ, ಖಾಖ್ರಾ ಅಥವಾ ಮೊಸರನ್ನ ತೆಗೆದುಕೊಂಡು ಹೋಗಿ; ಸೀಲ್ ಮಾಡಿದ ನೀರನ್ನು ಮಾತ್ರ ಕುಡಿಯಿರಿ.', 'ട്രെയിൻ: വീട്ടിൽ നിന്ന് തെപ്ല, ഇഡ്ലി, ഖാക്ര അല്ലെങ്കിൽ തൈര് സാദം കൊണ്ടുപോകുക; സീൽ ചെയ്ത വെള്ളം മാത്രം കുടിക്കുക.'],
    hotel: ['Hotel: at the buffet start with salad and protein, then a small portion of grains; skip pastries and juices.', 'होटल: बुफे में पहले सलाद और प्रोटीन लें, फिर थोड़ा अनाज; पेस्ट्री और जूस न लें।', 'हॉटेल: बुफेमध्ये आधी सॅलड व प्रथिने घ्या, मग थोडे धान्य; पेस्ट्री व ज्यूस टाळा.', 'હોટેલ: બુફેમાં પહેલાં સલાડ અને પ્રોટીન લો, પછી થોડું અનાજ; પેસ્ટ્રી અને જ્યૂસ ટાળો.', 'হোটেল: বুফেতে আগে স্যালাড ও প্রোটিন নিন, তারপর অল্প শস্য; পেস্ট্রি ও জুস এড়িয়ে চলুন।', 'ਹੋਟਲ: ਬੁਫ਼ੇ ਵਿੱਚ ਪਹਿਲਾਂ ਸਲਾਦ ਅਤੇ ਪ੍ਰੋਟੀਨ ਲਓ, ਫਿਰ ਥੋੜ੍ਹਾ ਅਨਾਜ; ਪੇਸਟਰੀ ਅਤੇ ਜੂਸ ਨਾ ਲਓ।', 'ஹோட்டல்: பஃபேயில் முதலில் சாலட் மற்றும் புரதம், பிறகு சிறிதளவு தானியம்; பேஸ்ட்ரி மற்றும் ஜூஸைத் தவிர்க்கவும்.', 'హోటల్: బఫేలో ముందు సలాడ్ మరియు ప్రోటీన్, తర్వాత కొద్దిగా ధాన్యం; పేస్ట్రీ, జ్యూస్ మానండి.', 'ಹೋಟೆಲ್: ಬಫೆಯಲ್ಲಿ ಮೊದಲು ಸಲಾಡ್ ಮತ್ತು ಪ್ರೋಟೀನ್, ನಂತರ ಸ್ವಲ್ಪ ಧಾನ್ಯ; ಪೇಸ್ಟ್ರಿ ಮತ್ತು ಜ್ಯೂಸ್ ತಪ್ಪಿಸಿ.', 'ഹോട്ടൽ: ബുഫേയിൽ ആദ്യം സാലഡും പ്രോട്ടീനും, പിന്നെ കുറച്ച് ധാന്യം; പേസ്ട്രിയും ജ്യൂസും ഒഴിവാക്കുക.'],
    road: ['Road trip: at dhabas choose dal, roti without butter, salad and curd.', 'सड़क यात्रा: ढाबे पर दाल, बिना मक्खन की रोटी, सलाद और दही चुनें।', 'रस्ता प्रवास: ढाब्यावर वरण, लोणी नसलेली रोटी, कोशिंबीर व दही निवडा.', 'રોડ ટ્રીપ: ઢાબા પર દાળ, માખણ વગરની રોટલી, સલાડ અને દહીં પસંદ કરો.', 'সড়ক যাত্রা: ধাবায় ডাল, মাখন ছাড়া রুটি, স্যালাড ও দই বেছে নিন।', 'ਸੜਕ ਯਾਤਰਾ: ਢਾਬੇ \'ਤੇ ਦਾਲ, ਬਿਨਾਂ ਮੱਖਣ ਰੋਟੀ, ਸਲਾਦ ਅਤੇ ਦਹੀਂ ਚੁਣੋ।', 'சாலைப் பயணம்: தாபாவில் பருப்பு, வெண்ணெய் இல்லாத ரொட்டி, சாலட் மற்றும் தயிர் தேர்ந்தெடுக்கவும்.', 'రోడ్డు ప్రయాణం: ధాబాలో పప్పు, వెన్న లేని రొట్టె, సలాడ్ మరియు పెరుగు ఎంచుకోండి.', 'ರಸ್ತೆ ಪ್ರಯಾಣ: ಢಾಬಾದಲ್ಲಿ ಬೇಳೆ, ಬೆಣ್ಣೆ ಇಲ್ಲದ ರೊಟ್ಟಿ, ಸಲಾಡ್ ಮತ್ತು ಮೊಸರು ಆರಿಸಿ.', 'റോഡ് യാത്ര: ധാബയിൽ പരിപ്പ്, വെണ്ണയില്ലാത്ത റൊട്ടി, സാലഡ്, തൈര് എന്നിവ തിരഞ്ഞെടുക്കുക.'],
    jain: ['Jain: cook without onion, garlic, ginger and root vegetables.', 'जैन: प्याज़, लहसुन, अदरक और ज़मीकंद के बिना पकाएं।', 'जैन: कांदा, लसूण, आले व कंदमुळांशिवाय स्वयंपाक करा.', 'જૈન: ડુંગળી, લસણ, આદુ અને કંદમૂળ વગર રાંધો.', 'জৈন: পেঁয়াজ, রসুন, আদা ও মূলজাতীয় সবজি ছাড়া রান্না করুন।', 'ਜੈਨ: ਪਿਆਜ਼, ਲਸਣ, ਅਦਰਕ ਅਤੇ ਜੜ੍ਹ ਵਾਲੀਆਂ ਸਬਜ਼ੀਆਂ ਤੋਂ ਬਿਨਾਂ ਪਕਾਓ।', 'ஜைன: வெங்காயம், பூண்டு, இஞ்சி மற்றும் கிழங்குகள் இல்லாமல் சமைக்கவும்.', 'జైన: ఉల్లి, వెల్లుల్లి, అల్లం మరియు దుంపలు లేకుండా వండండి.', 'ಜೈನ: ಈರುಳ್ಳಿ, ಬೆಳ್ಳುಳ್ಳಿ, ಶುಂಠಿ ಮತ್ತು ಗೆಡ್ಡೆಗಳಿಲ್ಲದೆ ಬೇಯಿಸಿ.', 'ജൈന: ഉള്ളി, വെളുത്തുള്ളി, ഇഞ്ചി, കിഴങ്ങുകൾ എന്നിവയില്ലാതെ പാചകം ചെയ്യുക.'],
    lose: ['Weight loss: finish dinner 2–3 hours before bed, walk 30–45 minutes daily and sleep 7–8 hours.', 'वज़न घटाना: सोने से 2–3 घंटे पहले रात का भोजन करें, रोज़ 30–45 मिनट टहलें और 7–8 घंटे सोएं।', 'वजन कमी करणे: झोपण्याच्या 2–3 तास आधी जेवण करा, रोज 30–45 मिनिटे चाला आणि 7–8 तास झोपा.', 'વજન ઘટાડવા: સૂવાના 2–3 કલાક પહેલાં જમી લો, રોજ 30–45 મિનિટ ચાલો અને 7–8 કલાક ઊંઘો.', 'ওজন কমানো: ঘুমের 2–3 ঘণ্টা আগে রাতের খাবার শেষ করুন, রোজ 30–45 মিনিট হাঁটুন এবং 7–8 ঘণ্টা ঘুমান।', 'ਭਾਰ ਘਟਾਉਣਾ: ਸੌਣ ਤੋਂ 2–3 ਘੰਟੇ ਪਹਿਲਾਂ ਰਾਤ ਦਾ ਖਾਣਾ ਖਾਓ, ਰੋਜ਼ 30–45 ਮਿੰਟ ਸੈਰ ਕਰੋ ਅਤੇ 7–8 ਘੰਟੇ ਸੌਂਵੋ।', 'எடை குறைப்பு: தூங்குவதற்கு 2–3 மணி நேரம் முன் இரவு உணவை முடிக்கவும், தினமும் 30–45 நிமிடம் நடக்கவும், 7–8 மணி நேரம் தூங்கவும்.', 'బరువు తగ్గడం: నిద్రకు 2–3 గంటల ముందు రాత్రి భోజనం ముగించండి, రోజూ 30–45 నిమిషాలు నడవండి, 7–8 గంటలు నిద్రపోండి.', 'ತೂಕ ಇಳಿಕೆ: ಮಲಗುವ 2–3 ಗಂಟೆ ಮೊದಲು ರಾತ್ರಿ ಊಟ ಮುಗಿಸಿ, ಪ್ರತಿದಿನ 30–45 ನಿಮಿಷ ನಡೆಯಿರಿ ಮತ್ತು 7–8 ಗಂಟೆ ನಿದ್ರಿಸಿ.', 'ഭാരം കുറയ്ക്കൽ: ഉറങ്ങുന്നതിന് 2–3 മണിക്കൂർ മുമ്പ് അത്താഴം കഴിക്കുക, ദിവസവും 30–45 മിനിറ്റ് നടക്കുക, 7–8 മണിക്കൂർ ഉറങ്ങുക.'],
    gain: ['Do not skip snacks; do strength training 3–4 times a week.', 'नाश्ते न छोड़ें; सप्ताह में 3–4 बार स्ट्रेंथ ट्रेनिंग करें।', 'मधले खाणे चुकवू नका; आठवड्यातून 3–4 वेळा व्यायाम (स्ट्रेंथ ट्रेनिंग) करा.', 'નાસ્તો છોડશો નહીં; અઠવાડિયામાં 3–4 વાર સ્ટ્રેન્થ ટ્રેનિંગ કરો.', 'জলখাবার বাদ দেবেন না; সপ্তাহে 3–4 বার শক্তি-ব্যায়াম করুন।', 'ਸਨੈਕਸ ਨਾ ਛੱਡੋ; ਹਫ਼ਤੇ ਵਿੱਚ 3–4 ਵਾਰ ਸਟ੍ਰੈਂਥ ਟ੍ਰੇਨਿੰਗ ਕਰੋ।', 'சிற்றுண்டிகளைத் தவிர்க்க வேண்டாம்; வாரத்தில் 3–4 முறை வலிமைப் பயிற்சி செய்யவும்.', 'స్నాక్స్ మానవద్దు; వారానికి 3–4 సార్లు బల వ్యాయామం చేయండి.', 'ತಿಂಡಿಗಳನ್ನು ಬಿಡಬೇಡಿ; ವಾರಕ್ಕೆ 3–4 ಬಾರಿ ಶಕ್ತಿ ವ್ಯಾಯಾಮ ಮಾಡಿ.', 'ലഘുഭക്ഷണങ്ങൾ ഒഴിവാക്കരുത്; ആഴ്ചയിൽ 3–4 തവണ സ്ട്രെങ്ത് ട്രെയിനിംഗ് ചെയ്യുക.'],
    pregnancy: ['Pregnancy: take iron, folic acid and calcium as prescribed; avoid raw papaya, unpasteurised milk and alcohol.', 'गर्भावस्था: आयरन, फोलिक एसिड और कैल्शियम डॉक्टर के अनुसार लें; कच्चा पपीता, कच्चा दूध और शराब से बचें।', 'गर्भावस्था: लोह, फॉलिक ॲसिड व कॅल्शियम डॉक्टरांच्या सल्ल्यानुसार घ्या; कच्ची पपई, कच्चे दूध व मद्य टाळा.', 'ગર્ભાવસ્થા: આયર્ન, ફોલિક એસિડ અને કેલ્શિયમ ડૉક્ટરની સલાહ મુજબ લો; કાચું પપૈયું, કાચું દૂધ અને દારૂ ટાળો.', 'গর্ভাবস্থা: ডাক্তারের পরামর্শমতো আয়রন, ফলিক অ্যাসিড ও ক্যালসিয়াম নিন; কাঁচা পেঁপে, কাঁচা দুধ ও মদ এড়িয়ে চলুন।', 'ਗਰਭ ਅਵਸਥਾ: ਆਇਰਨ, ਫੋਲਿਕ ਐਸਿਡ ਅਤੇ ਕੈਲਸ਼ੀਅਮ ਡਾਕਟਰ ਅਨੁਸਾਰ ਲਓ; ਕੱਚਾ ਪਪੀਤਾ, ਕੱਚਾ ਦੁੱਧ ਅਤੇ ਸ਼ਰਾਬ ਤੋਂ ਬਚੋ।', 'கர்ப்பகாலம்: இரும்பு, ஃபோலிக் அமிலம், கால்சியம் மருத்துவர் கூறியபடி எடுக்கவும்; பச்சை பப்பாளி, காய்ச்சாத பால், மது தவிர்க்கவும்.', 'గర్భధారణ: ఐరన్, ఫోలిక్ యాసిడ్, కాల్షియం డాక్టర్ సూచన మేరకు తీసుకోండి; పచ్చి బొప్పాయి, కాచని పాలు, మద్యం మానండి.', 'ಗರ್ಭಾವಸ್ಥೆ: ಕಬ್ಬಿಣ, ಫೋಲಿಕ್ ಆಮ್ಲ ಮತ್ತು ಕ್ಯಾಲ್ಸಿಯಂ ವೈದ್ಯರ ಸಲಹೆಯಂತೆ ತೆಗೆದುಕೊಳ್ಳಿ; ಹಸಿ ಪಪ್ಪಾಯಿ, ಕಾಯಿಸದ ಹಾಲು ಮತ್ತು ಮದ್ಯ ತಪ್ಪಿಸಿ.', 'ഗർഭകാലം: ഇരുമ്പ്, ഫോളിക് ആസിഡ്, കാൽസ്യം എന്നിവ ഡോക്ടർ നിർദ്ദേശിച്ചതുപോലെ കഴിക്കുക; പച്ച പപ്പായ, തിളപ്പിക്കാത്ത പാൽ, മദ്യം എന്നിവ ഒഴിവാക്കുക.'],
    lactation: ['Breastfeeding: drink a glass of water or milk at every feed; include methi, jeera, ajwain and dals.', 'स्तनपान: हर बार दूध पिलाते समय एक गिलास पानी या दूध पिएं; मेथी, जीरा, अजवाइन और दालें शामिल करें।', 'स्तनपान: प्रत्येक वेळी पाजताना एक ग्लास पाणी किंवा दूध प्या; मेथी, जिरे, ओवा व डाळी घ्या.', 'સ્તનપાન: દરેક વખતે ધવડાવતી વખતે એક ગ્લાસ પાણી કે દૂધ પીવો; મેથી, જીરું, અજમો અને દાળ લો.', 'স্তন্যদান: প্রতিবার খাওয়ানোর সময় এক গ্লাস জল বা দুধ পান করুন; মেথি, জিরে, জোয়ান ও ডাল রাখুন।', 'ਦੁੱਧ ਚੁੰਘਾਉਣਾ: ਹਰ ਵਾਰ ਇੱਕ ਗਲਾਸ ਪਾਣੀ ਜਾਂ ਦੁੱਧ ਪੀਓ; ਮੇਥੀ, ਜੀਰਾ, ਅਜਵਾਇਣ ਅਤੇ ਦਾਲਾਂ ਸ਼ਾਮਲ ਕਰੋ।', 'தாய்ப்பால்: ஒவ்வொரு முறையும் ஒரு டம்ளர் தண்ணீர் அல்லது பால் குடிக்கவும்; வெந்தயம், சீரகம், ஓமம், பருப்புகள் சேர்க்கவும்.', 'పాలిచ్చేటప్పుడు: ప్రతిసారీ ఒక గ్లాసు నీరు లేదా పాలు తాగండి; మెంతులు, జీలకర్ర, వాము, పప్పులు చేర్చండి.', 'ಹಾಲುಣಿಸುವಾಗ: ಪ್ರತಿ ಬಾರಿ ಒಂದು ಲೋಟ ನೀರು ಅಥವಾ ಹಾಲು ಕುಡಿಯಿರಿ; ಮೆಂತ್ಯ, ಜೀರಿಗೆ, ಓಮ ಮತ್ತು ಬೇಳೆಗಳನ್ನು ಸೇರಿಸಿ.', 'മുലയൂട്ടൽ: ഓരോ തവണയും ഒരു ഗ്ലാസ് വെള്ളമോ പാലോ കുടിക്കുക; ഉലുവ, ജീരകം, അയമോദകം, പരിപ്പ് എന്നിവ ഉൾപ്പെടുത്തുക.'],
    diabetes: ['Diabetes: choose whole grains and pair carbs with protein; avoid sugar, jaggery, juices and sweets; check blood sugar regularly.', 'मधुमेह: साबुत अनाज चुनें और कार्ब्स के साथ प्रोटीन लें; चीनी, गुड़, जूस और मिठाई से बचें; शुगर नियमित जांचें।', 'मधुमेह: अख्खी धान्ये निवडा व कर्बोदकांसोबत प्रथिने घ्या; साखर, गूळ, ज्यूस व मिठाई टाळा; साखर नियमित तपासा.', 'ડાયાબિટીસ: આખાં અનાજ પસંદ કરો અને કાર્બ્સ સાથે પ્રોટીન લો; ખાંડ, ગોળ, જ્યૂસ અને મીઠાઈ ટાળો; શુગર નિયમિત તપાસો.', 'ডায়াবেটিস: গোটা শস্য বেছে নিন এবং কার্বের সঙ্গে প্রোটিন খান; চিনি, গুড়, জুস ও মিষ্টি এড়িয়ে চলুন; নিয়মিত সুগার পরীক্ষা করুন।', 'ਸ਼ੂਗਰ: ਸਾਬਤ ਅਨਾਜ ਚੁਣੋ ਅਤੇ ਕਾਰਬਸ ਨਾਲ ਪ੍ਰੋਟੀਨ ਲਓ; ਖੰਡ, ਗੁੜ, ਜੂਸ ਅਤੇ ਮਿਠਾਈ ਤੋਂ ਬਚੋ; ਸ਼ੂਗਰ ਨਿਯਮਿਤ ਜਾਂਚੋ।', 'நீரிழிவு: முழு தானியங்களைத் தேர்ந்தெடுத்து மாவுச்சத்துடன் புரதம் சேர்க்கவும்; சர்க்கரை, வெல்லம், ஜூஸ், இனிப்புகள் தவிர்க்கவும்; சர்க்கரை அளவை தவறாமல் பரிசோதிக்கவும்.', 'మధుమేహం: తృణధాన్యాలు ఎంచుకోండి, పిండిపదార్థాలతో ప్రోటీన్ కలపండి; చక్కెర, బెల్లం, జ్యూస్, స్వీట్లు మానండి; షుగర్ క్రమం తప్పకుండా చూసుకోండి.', 'ಮಧುಮೇಹ: ಪೂರ್ಣ ಧಾನ್ಯ ಆರಿಸಿ ಮತ್ತು ಕಾರ್ಬ್ಸ್ ಜೊತೆ ಪ್ರೋಟೀನ್ ಸೇರಿಸಿ; ಸಕ್ಕರೆ, ಬೆಲ್ಲ, ಜ್ಯೂಸ್, ಸಿಹಿ ತಪ್ಪಿಸಿ; ಸಕ್ಕರೆ ಮಟ್ಟ ನಿಯಮಿತವಾಗಿ ಪರೀಕ್ಷಿಸಿ.', 'പ്രമേഹം: മുഴുധാന്യങ്ങൾ തിരഞ്ഞെടുക്കുക, കാർബ്സിനൊപ്പം പ്രോട്ടീൻ കഴിക്കുക; പഞ്ചസാര, ശർക്കര, ജ്യൂസ്, മധുരം ഒഴിവാക്കുക; ഷുഗർ പതിവായി പരിശോധിക്കുക.'],
    bp: ['High BP: less than 5 g salt (1 tsp) a day; avoid pickles, papad, namkeen and packaged foods.', 'हाई बीपी: दिन में 5 ग्राम (1 छोटा चम्मच) से कम नमक; अचार, पापड़, नमकीन और पैकेट वाले भोजन से बचें।', 'उच्च रक्तदाब: दिवसाला 5 ग्रॅम (1 छोटा चमचा) पेक्षा कमी मीठ; लोणचे, पापड, फरसाण व पॅकबंद पदार्थ टाळा.', 'હાઈ બીપી: દિવસમાં 5 ગ્રામ (1 ચમચી) થી ઓછું મીઠું; અથાણાં, પાપડ, નમકીન અને પેકેટવાળા ખોરાક ટાળો.', 'উচ্চ রক্তচাপ: দিনে 5 গ্রাম (1 চা চামচ)-এর কম লবণ; আচার, পাঁপড়, নোনতা ও প্যাকেটজাত খাবার এড়িয়ে চলুন।', 'ਹਾਈ ਬੀਪੀ: ਦਿਨ ਵਿੱਚ 5 ਗ੍ਰਾਮ (1 ਛੋਟਾ ਚਮਚ) ਤੋਂ ਘੱਟ ਲੂਣ; ਅਚਾਰ, ਪਾਪੜ, ਨਮਕੀਨ ਅਤੇ ਪੈਕੇਟ ਵਾਲੇ ਭੋਜਨ ਤੋਂ ਬਚੋ।', 'உயர் இரத்த அழுத்தம்: நாளொன்றுக்கு 5 கிராம் (1 தேக்கரண்டி) க்கும் குறைவான உப்பு; ஊறுகாய், அப்பளம், காரவகை, பாக்கெட் உணவுகள் தவிர்க்கவும்.', 'అధిక రక్తపోటు: రోజుకు 5 గ్రాముల (1 టీ స్పూన్) కంటే తక్కువ ఉప్పు; ఊరగాయలు, అప్పడాలు, నమ్కీన్, ప్యాకెట్ ఆహారాలు మానండి.', 'ಅಧಿಕ ರಕ್ತದೊತ್ತಡ: ದಿನಕ್ಕೆ 5 ಗ್ರಾಂ (1 ಟೀ ಚಮಚ) ಗಿಂತ ಕಡಿಮೆ ಉಪ್ಪು; ಉಪ್ಪಿನಕಾಯಿ, ಹಪ್ಪಳ, ಖಾರದ ತಿಂಡಿ ಮತ್ತು ಪ್ಯಾಕೆಟ್ ಆಹಾರ ತಪ್ಪಿಸಿ.', 'ഉയർന്ന രക്തസമ്മർദ്ദം: ദിവസം 5 ഗ്രാമിൽ (1 ടീസ്പൂൺ) താഴെ ഉപ്പ്; അച്ചാർ, പപ്പടം, മിക്സ്ചർ, പാക്കറ്റ് ഭക്ഷണങ്ങൾ ഒഴിവാക്കുക.'],
    pcos: ['PCOS: eat low-GI foods at regular times and exercise daily; limit sugar and maida.', 'पीसीओएस: नियमित समय पर लो-जीआई भोजन करें और रोज़ व्यायाम करें; चीनी और मैदा कम करें।', 'पीसीओएस: ठराविक वेळी कमी-जीआय आहार घ्या व रोज व्यायाम करा; साखर व मैदा कमी करा.', 'પીસીઓએસ: નિયમિત સમયે ઓછા-જીઆઈ ખોરાક લો અને રોજ કસરત કરો; ખાંડ અને મેંદો ઓછો કરો.', 'পিসিওএস: নির্দিষ্ট সময়ে লো-জিআই খাবার খান ও রোজ ব্যায়াম করুন; চিনি ও ময়দা কমান।', 'ਪੀਸੀਓਐਸ: ਨਿਯਮਿਤ ਸਮੇਂ \'ਤੇ ਘੱਟ-ਜੀਆਈ ਭੋਜਨ ਖਾਓ ਅਤੇ ਰੋਜ਼ ਕਸਰਤ ਕਰੋ; ਖੰਡ ਅਤੇ ਮੈਦਾ ਘਟਾਓ।', 'பிசிஓஎஸ்: குறைந்த-ஜிஐ உணவுகளை சரியான நேரத்தில் உண்டு, தினமும் உடற்பயிற்சி செய்யவும்; சர்க்கரை, மைதாவைக் குறைக்கவும்.', 'పీసీఓఎస్: క్రమమైన సమయాల్లో తక్కువ-జీఐ ఆహారం తినండి, రోజూ వ్యాయామం చేయండి; చక్కెర, మైదా తగ్గించండి.', 'ಪಿಸಿಒಎಸ್: ನಿಯಮಿತ ಸಮಯಕ್ಕೆ ಕಡಿಮೆ-ಜಿಐ ಆಹಾರ ಸೇವಿಸಿ ಮತ್ತು ಪ್ರತಿದಿನ ವ್ಯಾಯಾಮ ಮಾಡಿ; ಸಕ್ಕರೆ ಮತ್ತು ಮೈದಾ ಕಡಿಮೆ ಮಾಡಿ.', 'പിസിഒഎസ്: കൃത്യസമയത്ത് കുറഞ്ഞ-ജിഐ ഭക്ഷണം കഴിക്കുക, ദിവസവും വ്യായാമം ചെയ്യുക; പഞ്ചസാരയും മൈദയും കുറയ്ക്കുക.'],
    thyroid: ['Thyroid: take the tablet on an empty stomach, 30–60 minutes before breakfast or tea; eat cabbage, cauliflower and soy cooked.', 'थायरॉइड: दवा खाली पेट, नाश्ते या चाय से 30–60 मिनट पहले लें; पत्ता गोभी, फूलगोभी और सोया पकाकर खाएं।', 'थायरॉईड: गोळी उपाशीपोटी, नाश्ता किंवा चहाच्या 30–60 मिनिटे आधी घ्या; कोबी, फुलकोबी व सोया शिजवून खा.', 'થાઇરોઇડ: દવા ખાલી પેટે, નાસ્તા કે ચાના 30–60 મિનિટ પહેલાં લો; કોબી, ફ્લાવર અને સોયા રાંધીને ખાઓ.', 'থাইরয়েড: ওষুধ খালি পেটে, প্রাতরাশ বা চায়ের 30–60 মিনিট আগে খান; বাঁধাকপি, ফুলকপি ও সয়া রান্না করে খান।', 'ਥਾਇਰਾਇਡ: ਦਵਾਈ ਖਾਲੀ ਪੇਟ, ਨਾਸ਼ਤੇ ਜਾਂ ਚਾਹ ਤੋਂ 30–60 ਮਿੰਟ ਪਹਿਲਾਂ ਲਓ; ਬੰਦਗੋਭੀ, ਫੁੱਲਗੋਭੀ ਅਤੇ ਸੋਇਆ ਪਕਾ ਕੇ ਖਾਓ।', 'தைராய்டு: மாத்திரையை வெறும் வயிற்றில், காலை உணவு அல்லது டீக்கு 30–60 நிமிடம் முன் எடுக்கவும்; முட்டைக்கோஸ், காலிஃபிளவர், சோயாவை சமைத்து உண்ணவும்.', 'థైరాయిడ్: మాత్రను ఖాళీ కడుపుతో, అల్పాహారం లేదా టీకి 30–60 నిమిషాల ముందు వేసుకోండి; క్యాబేజీ, కాలీఫ్లవర్, సోయా వండి తినండి.', 'ಥೈರಾಯ್ಡ್: ಮಾತ್ರೆಯನ್ನು ಖಾಲಿ ಹೊಟ್ಟೆಯಲ್ಲಿ, ಉಪಾಹಾರ ಅಥವಾ ಟೀಗೆ 30–60 ನಿಮಿಷ ಮೊದಲು ತೆಗೆದುಕೊಳ್ಳಿ; ಎಲೆಕೋಸು, ಹೂಕೋಸು ಮತ್ತು ಸೋಯಾ ಬೇಯಿಸಿ ತಿನ್ನಿ.', 'തൈറോയ്ഡ്: ഗുളിക വെറും വയറ്റിൽ, പ്രഭാതഭക്ഷണത്തിനോ ചായയ്ക്കോ 30–60 മിനിറ്റ് മുമ്പ് കഴിക്കുക; കാബേജ്, കോളിഫ്ലവർ, സോയ എന്നിവ വേവിച്ച് കഴിക്കുക.'],
    cholesterol: ['Cholesterol: limit fried food, ghee, butter and red meat; add oats, flaxseed and nuts.', 'कोलेस्ट्रॉल: तला भोजन, घी, मक्खन और रेड मीट कम करें; ओट्स, अलसी और मेवे शामिल करें।', 'कोलेस्टेरॉल: तळलेले पदार्थ, तूप, लोणी व रेड मीट कमी करा; ओट्स, जवस व सुकामेवा घ्या.', 'કોલેસ્ટ્રોલ: તળેલું, ઘી, માખણ અને રેડ મીટ ઓછું કરો; ઓટ્સ, અળસી અને સૂકો મેવો ઉમેરો.', 'কোলেস্টেরল: ভাজা খাবার, ঘি, মাখন ও রেড মিট কমান; ওটস, তিসি ও বাদাম যোগ করুন।', 'ਕੋਲੈਸਟ੍ਰੋਲ: ਤਲਿਆ ਭੋਜਨ, ਘਿਓ, ਮੱਖਣ ਅਤੇ ਰੈੱਡ ਮੀਟ ਘਟਾਓ; ਓਟਸ, ਅਲਸੀ ਅਤੇ ਮੇਵੇ ਸ਼ਾਮਲ ਕਰੋ।', 'கொலஸ்ட்ரால்: பொரித்த உணவு, நெய், வெண்ணெய், சிவப்பு இறைச்சியைக் குறைக்கவும்; ஓட்ஸ், ஆளிவிதை, பருப்புகள் சேர்க்கவும்.', 'కొలెస్ట్రాల్: వేపుళ్లు, నెయ్యి, వెన్న, రెడ్ మీట్ తగ్గించండి; ఓట్స్, అవిసె గింజలు, గింజలు చేర్చండి.', 'ಕೊಲೆಸ್ಟ್ರಾಲ್: ಕರಿದ ಆಹಾರ, ತುಪ್ಪ, ಬೆಣ್ಣೆ ಮತ್ತು ಕೆಂಪು ಮಾಂಸ ಕಡಿಮೆ ಮಾಡಿ; ಓಟ್ಸ್, ಅಗಸೆ ಬೀಜ ಮತ್ತು ಬೀಜಗಳನ್ನು ಸೇರಿಸಿ.', 'കൊളസ്ട്രോൾ: വറുത്തവ, നെയ്യ്, വെണ്ണ, ചുവന്ന മാംസം കുറയ്ക്കുക; ഓട്സ്, ചണവിത്ത്, നട്സ് എന്നിവ ചേർക്കുക.'],
    fattyliver: ['Fatty liver: avoid alcohol, sugar, maida and fried food; lose weight slowly.', 'फैटी लिवर: शराब, चीनी, मैदा और तले भोजन से बचें; धीरे-धीरे वज़न घटाएं।', 'फॅटी लिव्हर: मद्य, साखर, मैदा व तळलेले पदार्थ टाळा; हळूहळू वजन कमी करा.', 'ફેટી લિવર: દારૂ, ખાંડ, મેંદો અને તળેલું ટાળો; ધીમે ધીમે વજન ઘટાડો.', 'ফ্যাটি লিভার: মদ, চিনি, ময়দা ও ভাজা খাবার এড়িয়ে চলুন; ধীরে ধীরে ওজন কমান।', 'ਫੈਟੀ ਲਿਵਰ: ਸ਼ਰਾਬ, ਖੰਡ, ਮੈਦਾ ਅਤੇ ਤਲੇ ਭੋਜਨ ਤੋਂ ਬਚੋ; ਹੌਲੀ-ਹੌਲੀ ਭਾਰ ਘਟਾਓ।', 'கொழுப்பு கல்லீரல்: மது, சர்க்கரை, மைதா, பொரித்த உணவுகளைத் தவிர்க்கவும்; மெதுவாக எடையைக் குறைக்கவும்.', 'ఫ్యాటీ లివర్: మద్యం, చక్కెర, మైదా, వేపుళ్లు మానండి; నెమ్మదిగా బరువు తగ్గండి.', 'ಫ್ಯಾಟಿ ಲಿವರ್: ಮದ್ಯ, ಸಕ್ಕರೆ, ಮೈದಾ ಮತ್ತು ಕರಿದ ಆಹಾರ ತಪ್ಪಿಸಿ; ನಿಧಾನವಾಗಿ ತೂಕ ಇಳಿಸಿ.', 'ഫാറ്റി ലിവർ: മദ്യം, പഞ്ചസാര, മൈദ, വറുത്തവ ഒഴിവാക്കുക; പതുക്കെ ഭാരം കുറയ്ക്കുക.'],
    kidney: ['Kidney disease: protein, salt and potassium are limited; soak and boil vegetables before cooking; follow your nephrologist for fluids.', 'किडनी रोग: प्रोटीन, नमक और पोटैशियम सीमित हैं; सब्ज़ियों को पकाने से पहले भिगोकर उबालें; पानी की मात्रा डॉक्टर के अनुसार रखें।', 'मूत्रपिंड विकार: प्रथिने, मीठ व पोटॅशियम मर्यादित आहे; भाज्या शिजवण्यापूर्वी भिजवून उकळा; पाण्याचे प्रमाण डॉक्टरांच्या सल्ल्यानुसार ठेवा.', 'કિડની રોગ: પ્રોટીન, મીઠું અને પોટેશિયમ મર્યાદિત છે; શાકભાજી રાંધતા પહેલાં પલાળીને ઉકાળો; પાણીનું પ્રમાણ ડૉક્ટર મુજબ રાખો.', 'কিডনি রোগ: প্রোটিন, লবণ ও পটাশিয়াম সীমিত; রান্নার আগে সবজি ভিজিয়ে সেদ্ধ করুন; জলের পরিমাণ ডাক্তারের পরামর্শমতো রাখুন।', 'ਗੁਰਦੇ ਦੀ ਬਿਮਾਰੀ: ਪ੍ਰੋਟੀਨ, ਲੂਣ ਅਤੇ ਪੋਟਾਸ਼ੀਅਮ ਸੀਮਤ ਹਨ; ਸਬਜ਼ੀਆਂ ਪਕਾਉਣ ਤੋਂ ਪਹਿਲਾਂ ਭਿਓਂ ਕੇ ਉਬਾਲੋ; ਪਾਣੀ ਦੀ ਮਾਤਰਾ ਡਾਕਟਰ ਅਨੁਸਾਰ ਰੱਖੋ।', 'சிறுநீரக நோய்: புரதம், உப்பு, பொட்டாசியம் கட்டுப்படுத்தப்பட்டுள்ளன; காய்கறிகளை சமைக்கும் முன் ஊறவைத்து வேகவைக்கவும்; தண்ணீர் அளவை மருத்துவர் கூறியபடி வைக்கவும்.', 'కిడ్నీ వ్యాధి: ప్రోటీన్, ఉప్పు, పొటాషియం పరిమితం; కూరగాయలను వండే ముందు నానబెట్టి ఉడికించండి; నీటి మోతాదు డాక్టర్ సూచన మేరకు.', 'ಮೂತ್ರಪಿಂಡ ಕಾಯಿಲೆ: ಪ್ರೋಟೀನ್, ಉಪ್ಪು ಮತ್ತು ಪೊಟ್ಯಾಸಿಯಂ ಮಿತಿಯಲ್ಲಿವೆ; ತರಕಾರಿಗಳನ್ನು ಬೇಯಿಸುವ ಮೊದಲು ನೆನೆಸಿ ಕುದಿಸಿ; ನೀರಿನ ಪ್ರಮಾಣ ವೈದ್ಯರ ಸಲಹೆಯಂತೆ.', 'വൃക്കരോഗം: പ്രോട്ടീൻ, ഉപ്പ്, പൊട്ടാസ്യം പരിമിതമാണ്; പച്ചക്കറികൾ പാചകത്തിന് മുമ്പ് കുതിർത്ത് തിളപ്പിക്കുക; വെള്ളത്തിന്റെ അളവ് ഡോക്ടർ നിർദ്ദേശപ്രകാരം.'],
    bmiHigh: ['BMI is above the healthy range for Indians (18.5–22.9); a weight-loss goal is advised.', 'बीएमआई भारतीयों की स्वस्थ सीमा (18.5–22.9) से अधिक है; वज़न घटाने की सलाह है।', 'बीएमआय भारतीयांच्या निरोगी मर्यादेपेक्षा (18.5–22.9) जास्त आहे; वजन कमी करण्याचा सल्ला आहे.', 'બીએમઆઈ ભારતીયો માટેની સ્વસ્થ મર્યાદા (18.5–22.9) થી વધુ છે; વજન ઘટાડવાની સલાહ છે.', 'বিএমআই ভারতীয়দের স্বাস্থ্যকর সীমার (18.5–22.9) বেশি; ওজন কমানোর পরামর্শ দেওয়া হচ্ছে।', 'ਬੀਐਮਆਈ ਭਾਰਤੀਆਂ ਲਈ ਸਿਹਤਮੰਦ ਹੱਦ (18.5–22.9) ਤੋਂ ਵੱਧ ਹੈ; ਭਾਰ ਘਟਾਉਣ ਦੀ ਸਲਾਹ ਹੈ।', 'பிஎம்ஐ இந்தியர்களுக்கான ஆரோக்கிய வரம்பை (18.5–22.9) விட அதிகம்; எடை குறைப்பு பரிந்துரைக்கப்படுகிறது.', 'బీఎంఐ భారతీయుల ఆరోగ్య పరిధి (18.5–22.9) కంటే ఎక్కువ; బరువు తగ్గడం సూచించబడింది.', 'ಬಿಎಂಐ ಭಾರತೀಯರ ಆರೋಗ್ಯಕರ ಮಿತಿ (18.5–22.9) ಗಿಂತ ಹೆಚ್ಚು; ತೂಕ ಇಳಿಸಲು ಸಲಹೆ.', 'ബിഎംഐ ഇന്ത്യക്കാർക്കുള്ള ആരോഗ്യകരമായ പരിധിയിൽ (18.5–22.9) കൂടുതലാണ്; ഭാരം കുറയ്ക്കാൻ നിർദ്ദേശിക്കുന്നു.'],
    bmiLow: ['BMI is below the healthy range; weight loss is not advised.', 'बीएमआई स्वस्थ सीमा से कम है; वज़न घटाने की सलाह नहीं है।', 'बीएमआय निरोगी मर्यादेपेक्षा कमी आहे; वजन कमी करू नये.', 'બીએમઆઈ સ્વસ્થ મર્યાદાથી ઓછું છે; વજન ઘટાડવાની સલાહ નથી.', 'বিএমআই স্বাস্থ্যকর সীমার কম; ওজন কমানো উচিত নয়।', 'ਬੀਐਮਆਈ ਸਿਹਤਮੰਦ ਹੱਦ ਤੋਂ ਘੱਟ ਹੈ; ਭਾਰ ਘਟਾਉਣ ਦੀ ਸਲਾਹ ਨਹੀਂ।', 'பிஎம்ஐ ஆரோக்கிய வரம்பை விடக் குறைவு; எடை குறைப்பு பரிந்துரைக்கப்படவில்லை.', 'బీఎంఐ ఆరోగ్య పరిధి కంటే తక్కువ; బరువు తగ్గడం సూచించబడదు.', 'ಬಿಎಂಐ ಆರೋಗ್ಯಕರ ಮಿತಿಗಿಂತ ಕಡಿಮೆ; ತೂಕ ಇಳಿಸುವುದು ಸೂಕ್ತವಲ್ಲ.', 'ബിഎംഐ ആരോഗ്യകരമായ പരിധിയിൽ താഴെയാണ്; ഭാരം കുറയ്ക്കരുത്.'],
    proteinGap: ['Meals give about {avg} g protein a day (target {target} g); add paneer, curd, dal, sprouts, soya, eggs or lean meat as allowed.', 'भोजन से रोज़ लगभग {avg} ग्राम प्रोटीन मिलता है (लक्ष्य {target} ग्राम); अनुमति अनुसार पनीर, दही, दाल, स्प्राउट्स, सोया, अंडे या लीन मीट जोड़ें।', 'जेवणातून दररोज सुमारे {avg} ग्रॅम प्रथिने मिळतात (लक्ष्य {target} ग्रॅम); पनीर, दही, डाळ, मोड आलेली कडधान्ये, सोया, अंडी किंवा मांस वाढवा.', 'ભોજનમાંથી રોજ લગભગ {avg} ગ્રામ પ્રોટીન મળે છે (લક્ષ્ય {target} ગ્રામ); પનીર, દહીં, દાળ, ફણગાવેલાં કઠોળ, સોયા, ઈંડાં કે માંસ ઉમેરો.', 'খাবার থেকে দিনে প্রায় {avg} গ্রাম প্রোটিন আসে (লক্ষ্য {target} গ্রাম); অনুমতি অনুযায়ী পনির, দই, ডাল, অঙ্কুরিত ছোলা, সয়া, ডিম বা মাংস যোগ করুন।', 'ਭੋਜਨ ਤੋਂ ਰੋਜ਼ ਲਗਭਗ {avg} ਗ੍ਰਾਮ ਪ੍ਰੋਟੀਨ ਮਿਲਦਾ ਹੈ (ਟੀਚਾ {target} ਗ੍ਰਾਮ); ਪਨੀਰ, ਦਹੀਂ, ਦਾਲ, ਪੁੰਗਰੇ ਅਨਾਜ, ਸੋਇਆ, ਅੰਡੇ ਜਾਂ ਮੀਟ ਸ਼ਾਮਲ ਕਰੋ।', 'உணவிலிருந்து தினமும் சுமார் {avg} கிராம் புரதம் கிடைக்கிறது (இலக்கு {target} கிராம்); பனீர், தயிர், பருப்பு, முளைகட்டிய பயறு, சோயா, முட்டை அல்லது இறைச்சி சேர்க்கவும்.', 'భోజనం నుంచి రోజుకు సుమారు {avg} గ్రాముల ప్రోటీన్ లభిస్తుంది (లక్ష్యం {target} గ్రాములు); పనీర్, పెరుగు, పప్పు, మొలకలు, సోయా, గుడ్లు లేదా మాంసం చేర్చండి.', 'ಊಟದಿಂದ ದಿನಕ್ಕೆ ಸುಮಾರು {avg} ಗ್ರಾಂ ಪ್ರೋಟೀನ್ ಸಿಗುತ್ತದೆ (ಗುರಿ {target} ಗ್ರಾಂ); ಪನೀರ್, ಮೊಸರು, ಬೇಳೆ, ಮೊಳಕೆ ಕಾಳು, ಸೋಯಾ, ಮೊಟ್ಟೆ ಅಥವಾ ಮಾಂಸ ಸೇರಿಸಿ.', 'ഭക്ഷണത്തിൽ നിന്ന് ദിവസം ഏകദേശം {avg} ഗ്രാം പ്രോട്ടീൻ ലഭിക്കുന്നു (ലക്ഷ്യം {target} ഗ്രാം); പനീർ, തൈര്, പരിപ്പ്, മുളപ്പിച്ച പയർ, സോയ, മുട്ട അല്ലെങ്കിൽ മാംസം ചേർക്കുക.'],
  });

